"""Small, deterministic OOXML fixtures for the actual existing Office parser.
No renderer/parser mock and no user material. Regenerate with Python stdlib.
"""
from pathlib import Path
from zipfile import ZipFile, ZipInfo, ZIP_DEFLATED

ROOT = Path(__file__).parent

def archive(name, files):
    with ZipFile(ROOT / name, "w", compression=ZIP_DEFLATED) as output:
        for path, xml in files.items():
            entry = ZipInfo(path, (2026, 10, 8, 0, 0, 0))
            entry.compress_type = ZIP_DEFLATED
            output.writestr(entry, xml)

archive("reader-history.docx", {
    "[Content_Types].xml": '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>',
    "word/document.xml": '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>Historical Word revision</w:t></w:r></w:p><w:p><w:r><w:t>Exact old body, never Current.</w:t></w:r></w:p></w:body></w:document>',
})

